/* ================= o glossário dos indicadores (abas Protótipo e Pontos) =================

   GERADO a partir do rascunho medido da rodada de 13/09 (glossario_rascunho.json, montado
   por montar_glossario.py) e conferido de novo na fonte em 14/09. Não edite entrada por
   entrada à mão sem abrir a fonte: o campo `origem` de cada uma diz o arquivo e a linha (ou
   a skill) de onde a frase saiu, e é por ele que se confere.

   De onde vem cada coisa, e só daí:
   - o técnico coletivo, das colunas do Team Stats do Wyscout como `analisar_serieb.py` as
     junta (média das partidas do clube na temporada — NÃO é por 90);
   - o elenco, das contas de `analisar_serieb.py` sobre o arquivo técnico do Wyscout jogador
     e sobre o Transfermarkt;
   - o físico, das colunas do SkillCorner, lidas pela skill dados-skillcorner e pelos
     dicionários `DE_PARA*` de `gerar_raio_serieb.py`;
   - o técnico individual e as regras de juntar jogadores, de `gerar_prototipo.py`
     (`agrega_tecnico_individual`) e de `analisar_serieb.py` (`media_pond`);
   - as colunas das tabelas, das funções que as gravam (`gerar_prototipo.py`,
     `ranking_gaps.py`, `gerar_pontos.py`).

   Nada foi inventado. Onde a fonte não diz, o campo diz `nao_achei_fonte` e a lista
   `nao_achei_fonte` da entrada nomeia quais campos ficaram assim — preencher de cabeça seria
   afirmar mais do que o projeto sabe. O lado bom segue a mesma regra: só existe onde o
   catálogo pré-declarado (ou outra declaração citada em `lado_quem_declara`) o escreve; todo
   o físico e todo o técnico individual têm sinal 0 no catálogo e aparecem como "sem lado bom
   declarado", mesmo quando parece óbvio.

   O nome segue o vocabulário que a tela já usa (`PT_MEDIDA_CHAVE` e `PT_MEDIDA_PEDACOS` em
   proto.js): `nome_longo` é o que `ptNomeIndicador` escreve hoje, e `nome` é a forma curta
   para cabeçalho.

   NOMES CORRIGIDOS EM 14/09 (conserto_r5_nomes.js, no scratchpad da sessão 3b480dcb). Os nomes
   que diziam mais do que o dado foram trocados nos TRÊS campos (`nome`, `nome_longo`,
   `nome_simples`) — antes só a casca trocava o `nome`, e o cabeçalho de matriz seguia dizendo
   "Velocidade máxima". Cada entrada trocada guarda o motivo e o nome antigo em `nome_corrigido`:
   psv/psv99 e as de setor = "pico de velocidade (média dos jogos)" (o SkillCorner grava a média,
   entre os jogos, do pico de cada jogo — não o recorde); gk_def = "% de defesas"; defesa_vs_xg =
   conta do time, não do goleiro; ppda = por ação defensiva, não por desarme; e as colunas com
   unidade % cujo nome se lia como contagem (ti_*_ganhos/certos/com_sucesso, gk_pas, aprov*,
   bp_conv, pctFicou, pctArtilheiro, pctTop3, fidelidade_media) ganharam o % no nome.
   `aviso_nome` só continua onde o nome não está errado, mas confunde (a mesma coluna com dois
   nomes). Regra conferida por script em todas as entradas: nome_simples = nome_longo; unidade %
   mostra % no nome; régua "pico" diz pico e média; nenhum nome da lista de errados.

   NOMES CURTOS ENCURTADOS EM 14/09 (limpeza da tela, dono da casca). Só o campo `nome` (a forma de
   cabeçalho de matriz); `nome_longo` e `nome_simples` não mudaram. 25 entradas, as que aparecem em
   cabeçalho de matriz ou de tabela estreita: "Dist. em piques c/ bola" → "Dist. piques c/ bola",
   "Dist. alta veloc. c/ bola" → "Dist. alta vel. c/bola", "Dist. alta intens. c/ bola" →
   "Dist. alta int. c/bola" (e as "s/ bola", nos 4 setores e no time), "Concentração de minutos" →
   "Minutos concentrados", "Após vencer/perder, jogo a jogo" → "Pontos após vencer/perder". A fase
   (c/ bola, s/ bola) e o setor (que vem da chave) ficaram; conferido por script que nenhum nome novo
   repete o de outra medida (grupos de nome repetido entre medidas diferentes: 36 antes, 36 depois).
   Ficaram acima de 22 caracteres, de propósito: as 27 de "Esperado:/Sorte: … (mando e adv.)" — caberiam
   só com letra de código (M, M+A), que é jargão — e as 24 colunas "… (subiu×meio)", que sem a faixa
   ficariam com o mesmo nome para SM, SC, AM e AB.

   O LADO DAS RÉGUAS (eixos das etapas 8 e 9). Régua só tem lado bom quando o catálogo declara
   lado para TODOS os itens dela, no mesmo sentido do sinal que o item recebe na régua. O +1/−1
   dentro do eixo só alinha os itens para a média (gerar_prototipo.py:1499); não declara nada.
   Por isso Pressão e ritmo, Volume físico, Explosão, Bola aérea e parada e Dinheiro ficam "sem
   lado bom declarado" — e altura e valor de mercado também, fora da régua.

   COLUNAS DAS DUAS ABAS. Onde o Protótipo diz "quem subiu / quem caiu", a aba por pontos usa a
   faixa alta / baixa de pontos com a mesma chave interna (gerar_pontos.py:2276); o texto das
   colunas usadas nas duas abas diz as duas coisas.

   A ARMADILHA DAS RÉGUAS. `por` diz a régua de cada número e ela não se mistura:
   - "por jogo": média das partidas (técnico coletivo); a partida do Wyscout passa de 90 min;
   - "por 90": dividido por 90 minutos do jogo inteiro;
   - "por 30 min daquela fase" e "por minuto" com fase "com a bola do time" / "sem a bola":
     medidas de FASE. Elas NÃO se comparam com as de 90 minutos — só com outra da mesma fase;
     `compara_com_por_90` é false nelas;
   - "pico": média, entre os jogos rastreados, do pico de cada jogo — não é recorde;
   - "%": porcentagem; ids que terminam em `ganhos`, `certos` ou `com_sucesso` são %.

   ETAPA 6 NO MESMO ANO (14/09, noite, dono da casca). A tela da etapa 6 deixou de mostrar o ano
   seguinte: `rho`, `dispersao`, `referencia_dinheiro` e `truncamento` ficam no arquivo (o catálogo,
   o ranking_gaps e o proto_c ainda leem `rho`) e ganharam `nota` dizendo isso; a `nota` antiga da
   dispersão (cor pelo desfecho em t+1) saiu, porque a tela nova não desenha mais esse gráfico; o
   nome de `rho` passou a dizer "no ano seguinte", para não ser confundido com o do mesmo ano; a
   `origem` apontava para uma linha velha (971) e foi para a de hoje. Verbetes novos, conferidos no
   gerador (MESMO_ANO_DECL e mesmo_ano): `mesmo_ano`, `aproveitamento_pct`, `rho_mesmo_ano`,
   `ordem_por_forca`, `lista_inteira`. Editado aqui porque o rascunho de onde este arquivo nasceu
   (montar_glossario.py) mora no scratchpad de outra sessão, fora do projeto: quem remontar pelo
   rascunho perde estas mudanças.

   Quem usa: `ptGlossario(id)` para indicador, régua ou regra de juntar; `ptGlossarioColuna(k)`
   para coluna de tabela. As duas devolvem null quando não há entrada — e aí quem desenha
   escreve a ausência com motivo, não um traço. A tela procura nesta ordem: campo gravado pelo
   gerador (indicadores[].unidade / .definicao) -> este glossário -> ptNomeMedida. */

