/* Este arquivo carrega ANTES de proto.js (templates/index.html), então não chama nenhum
   helper pt… no topo: é só dado e duas funções de leitura.

   `hasOwnProperty` e não `PT_GLOSSARIO[id]`: um id como "constructor" ou "toString" acharia
   a função do Object e a tela escreveria lixo com cara de definição. */
function ptGlossario(id) {
  if (id === null || id === undefined) return null;
  const k = String(id);
  return Object.prototype.hasOwnProperty.call(PT_GLOSSARIO, k) ? PT_GLOSSARIO[k] : null;
}

/* Coluna de tabela mora em outro mapa porque a mesma chave pode ser indicador numa tabela e
   coluna em outra ("porta" é selo no catálogo e critério de entrada na etapa 10; "p" é
   coluna, não indicador). Misturar os dois faria uma sobrescrever a outra em silêncio. */
function ptGlossarioColuna(k) {
  if (k === null || k === undefined) return null;
  const c = String(k);
  return Object.prototype.hasOwnProperty.call(PT_GLOSSARIO_COLUNAS, c) ? PT_GLOSSARIO_COLUNAS[c] : null;
}
